import{t as e}from"./utils-COoNfFoj.js";var t={slug:`matt-village`,influencerName:`Matt Village`,influencerHandle:`@mattvillage`,influencerAvatarUrl:`${e}/matt-village-avatar.jpeg`,heroDescription:`As editor of the Mindstream Newsletter, I need to stay across AI trends every single day, but I don’t have time to trawl the internet anymore. Now, the tool pulls the hottest AI news and gives me recommendations so I can focus on what I actually love, which is writing for our amazing audience.`,assetTitle:`AI Trends Tracker`,screenshotUrl:`${e}/matt-village.png`,remixUrl:`https://www.perplexity.ai/computer/a/ai-trends-news-tracker-HmqkTudoR.er05qaP9FIYA`,promptTitle:`Try Matt's prompt`,promptText:`Build an AI-powered web app called “AI Trends/News Tracker & Newsletter Ideation Engine” that automatically aggregates and normalizes daily AI news from 20+ high-signal sources including Hugging Face, TechCrunch, X (Twitter), Substack, and arXiv, then uses NLP-based clustering to group stories into key themes such as foundation models, product launches, regulation, and research breakthroughs; layer on a weekly “column idea generator” that outputs 5 differentiated newsletter angles each week with a strong hook, unique perspective, and a fully drafted opening paragraph; include a competitor intelligence module that tracks top AI newsletters and summarizes what topics they covered so gaps and underreported angles are clearly surfaced; generate a Monday morning digest highlighting the most important stories with a “coverage saturation” score to identify ideas that are not yet widely discussed; maintain a persistent “idea bank” database that logs all generated ideas, tracks status (used, unused, scheduled), and enables filtering and retrieval; design the UI in a clean, modern light mode with strong visual hierarchy, using pink and purple accents for highlights, tags, and key insights, ensuring a dashboard-style experience with widgets for trends, clusters, ideas, and competitive gaps.`};export{t as default};
